#!/usr/bin/env bash
# Self-test for check-catalog-regex-sync.sh. Runs the gate against fixtures and
# asserts pass on a synced pair, fail on a regex prefix missing from the
# catalog. A gate whose regex silently stops matching is worse than no gate, so
# the gate ships with this test and CI runs it (see ../../../M1 grep-gate).
set -u
here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
gate="$here/check-catalog-regex-sync.sh"
fix="$here/fixtures"
rc=0

run() { # <expected-exit> <label> <filter> <catalog>
  local want=$1 label=$2 filter=$3 catalog=$4 got
  FILTER_FILE="$filter" CATALOG="$catalog" RE_VAR=CODE_PATH_RE \
    "$gate" >/dev/null 2>&1
  got=$?
  if [ "$got" -eq "$want" ]; then
    echo "PASS: $label (exit $got)"
  else
    echo "FAIL: $label (want exit $want, got $got)"
    rc=1
  fi
}

run 0 "synced regex/catalog passes"        "$fix/synced/filter.sh"  "$fix/synced/catalog.yaml"
run 1 "regex prefix absent from catalog"   "$fix/drift/filter.sh"   "$fix/drift/catalog.yaml"
run 1 "regex prefix present only in notes:, not paths:" "$fix/notes-only/filter.sh" "$fix/notes-only/catalog.yaml"
run 1 "regex prefix near-misses a sibling path (services vs services-old)" "$fix/boundary/filter.sh" "$fix/boundary/catalog.yaml"
run 1 "regex prefix present only in a nested block's own paths: key" "$fix/nested-paths/filter.sh" "$fix/nested-paths/catalog.yaml"
run 1 "regex prefix present only in notes: block-scalar prose shaped like paths:" "$fix/block-scalar/filter.sh" "$fix/block-scalar/catalog.yaml"
run 2 "regex alternative normalizes to empty (.* catch-all)" "$fix/empty-alternative/filter.sh" "$fix/synced/catalog.yaml"
run 1 "narrower regex misses a glob with a literal comma"   "$fix/comma-in-glob/filter.sh" "$fix/comma-in-glob/catalog.yaml"
run 0 "inline comment after a paths: array doesn't leak into the glob" "$fix/inline-comment/filter.sh" "$fix/inline-comment/catalog.yaml"
run 2 "trailing | drops an empty alternative that matches every path" "$fix/trailing-pipe/filter.sh" "$fix/synced/catalog.yaml"
run 1 "quoted string inside an inline comment doesn't leak into the glob" "$fix/inline-comment-quoted/filter.sh" "$fix/inline-comment-quoted/catalog.yaml"
run 2 "unescaped regex metacharacter is rejected, not treated as a literal" "$fix/unescaped-metachar/filter.sh" "$fix/synced/catalog.yaml"
run 0 "a backslash-escaped metacharacter stays supported as a literal"     "$fix/escaped-dot/filter.sh" "$fix/escaped-dot/catalog.yaml"
run 0 "a catalog glob containing its own ] is parsed whole, not truncated" "$fix/bracket-glob/filter.sh" "$fix/bracket-glob/catalog.yaml"
run 2 "an alternative missing a leading ^ is rejected"                    "$fix/unanchored-start/filter.sh" "$fix/synced/catalog.yaml"
run 2 "an alternative with no trailing boundary is rejected"              "$fix/unanchored-end/filter.sh"   "$fix/synced/catalog.yaml"
run 0 "a /.* boundary (wildcard after a real separator) stays supported"  "$fix/dot-star-boundary/filter.sh" "$fix/synced/catalog.yaml"
run 2 "an escaped literal pipe is rejected, not silently mis-split"       "$fix/escaped-pipe/filter.sh" "$fix/synced/catalog.yaml"
run 1 "an exact-anchored alternative can't cover a descendant-only glob"  "$fix/exact-match-descendant/filter.sh" "$fix/exact-match-descendant/catalog.yaml"
run 0 "a YAML-escaped quote inside a glob is parsed, not truncated"       "$fix/escaped-quote-in-glob/filter.sh" "$fix/escaped-quote-in-glob/catalog.yaml"
run 1 "a directory-form alternative can't cover an exact wildcard-free catalog value" "$fix/directory-alt-exact-catalog/filter.sh" "$fix/directory-alt-exact-catalog/catalog.yaml"
run 2 "a malformed paths: array (an unquoted element) is a hard error"    "$fix/malformed-paths-array/filter.sh" "$fix/malformed-paths-array/catalog.yaml"
run 2 "an unescaped anchor embedded mid-alternative is rejected"          "$fix/embedded-anchor/filter.sh" "$fix/synced/catalog.yaml"
run 2 "trailing non-comment content after ] is a hard error"              "$fix/trailing-garbage-after-bracket/filter.sh" "$fix/trailing-garbage-after-bracket/catalog.yaml"
run 2 "an unsupported YAML escape sequence is a hard error"               "$fix/unsupported-yaml-escape/filter.sh" "$fix/unsupported-yaml-escape/catalog.yaml"
run 2 "a leading comma in the paths: array is a hard error"               "$fix/leading-comma/filter.sh" "$fix/leading-comma/catalog.yaml"
run 2 "a doubled comma in the paths: array is a hard error"               "$fix/double-comma/filter.sh" "$fix/double-comma/catalog.yaml"
run 2 "an empty path string is a hard error even if another area is valid" "$fix/empty-path-string/filter.sh" "$fix/empty-path-string/catalog.yaml"
run 0 "a single trailing comma in the paths: array stays supported"       "$fix/trailing-comma-ok/filter.sh" "$fix/trailing-comma-ok/catalog.yaml"
run 1 "an escaped-literal alternative can't cover a bracket-class glob"   "$fix/escaped-bracket-literal/filter.sh" "$fix/escaped-bracket-literal/catalog.yaml"
run 1 "an escaped-literal alternative can't cover a ? wildcard glob"      "$fix/question-mark-variable/filter.sh" "$fix/question-mark-variable/catalog.yaml"
run 2 "an escaped trailing \\\$ is a literal, not an anchor, and has no boundary" "$fix/escaped-dollar-not-anchor/filter.sh" "$fix/escaped-dollar-not-anchor/catalog.yaml"
run 2 "an empty paths: array is a hard error even if another area is valid" "$fix/empty-paths-array/filter.sh" "$fix/empty-paths-array/catalog.yaml"
run 2 "a non-array paths: declaration is a hard error, not silently skipped" "$fix/non-array-paths/filter.sh" "$fix/non-array-paths/catalog.yaml"
run 0 "a directory-form alternative covers a genuine ancestor of an exact file" "$fix/directory-alt-ancestor-of-exact/filter.sh" "$fix/directory-alt-ancestor-of-exact/catalog.yaml"
run 2 "a trailing /** on the regex side is rejected (unreliable duplicate-quantifier semantics)" "$fix/double-star-regex-suffix/filter.sh" "$fix/synced/catalog.yaml"
run 2 "a combined /\$ suffix is rejected (distinct from a clean exact match)" "$fix/combined-suffix-slash-dollar/filter.sh" "$fix/synced/catalog.yaml"
run 0 "a /.*\$ suffix normalizes and passes just like the plain /.* form"  "$fix/combined-suffix-dotstar-dollar/filter.sh" "$fix/combined-suffix-dotstar-dollar/catalog.yaml"
run 2 "a combined suffix against an exact catalog file is rejected"        "$fix/combined-suffix-exact-file/filter.sh" "$fix/inline-comment/catalog.yaml"
run 2 "a backslash before an unrecognized character is rejected"           "$fix/unrecognized-escape/filter.sh" "$fix/synced/catalog.yaml"
run 0 "an escaped backslash decodes to one literal backslash, not zero"    "$fix/escaped-backslash-in-regex/filter.sh" "$fix/escaped-backslash-in-regex/catalog.yaml"
run 0 "an escaped backslash followed by a real \$ anchor is an exact match" "$fix/escaped-backslash-then-dollar/filter.sh" "$fix/escaped-backslash-then-dollar/catalog.yaml"
run 2 "leading/trailing whitespace in the normalized prefix is a hard error" "$fix/whitespace-in-prefix/filter.sh" "$fix/synced/catalog.yaml"
run 2 "a double-quoted assignment is a hard error (raw source text isn't the runtime value)" "$fix/double-quoted-assignment/filter.sh" "$fix/synced/catalog.yaml"
run 1 "an escaped-literal alternative can't cover a brace-expansion glob"   "$fix/brace-expansion-variable/filter.sh" "$fix/brace-expansion-variable/catalog.yaml"
run 2 "a concatenated single-quoted assignment is a hard error"            "$fix/concatenated-quoted-assignment/filter.sh" "$fix/synced/catalog.yaml"
run 2 "an extglob catalog glob is a hard error (unrecognized dialect)"     "$fix/extglob-catalog-glob/filter.sh" "$fix/extglob-catalog-glob/catalog.yaml"
run 2 "a leading ! catalog glob is a hard error (unrecognized negation)"   "$fix/leading-negation-glob/filter.sh" "$fix/leading-negation-glob/catalog.yaml"
run 0 "a backslash-escaped metacharacter in a catalog glob is literal, not a variable construct" "$fix/escaped-metachar-in-catalog-glob/filter.sh" "$fix/escaped-metachar-in-catalog-glob/catalog.yaml"
run 2 "multiple \$CODE_PATH_RE assignments (or assignment-shaped lines) is a hard error" "$fix/multiple-assignments/filter.sh" "$fix/synced/catalog.yaml"
run 2 "a += append is rejected by the whole-file grammar"                 "$fix/append-assignment/filter.sh" "$fix/synced/catalog.yaml"
run 2 "a backslash-newline line continuation is a hard error"             "$fix/line-continuation/filter.sh" "$fix/synced/catalog.yaml"
run 2 "an indirect assignment (printf -v with a split variable name) is a hard error" "$fix/indirect-assignment/filter.sh" "$fix/synced/catalog.yaml"
run 2 "an assignment wrapped in a conditional is a hard error"            "$fix/conditional-assignment/filter.sh" "$fix/synced/catalog.yaml"
run 2 "a duplicate paths: key within the same area is a hard error, not unioned" "$fix/duplicate-paths-key/filter.sh" "$fix/duplicate-paths-key/catalog.yaml"
run 2 "a comment between duplicate paths: keys doesn't reset the duplicate tracker" "$fix/duplicate-paths-key-comment-between/filter.sh" "$fix/duplicate-paths-key-comment-between/catalog.yaml"
run 1 "a paths: key outside areas: is not a real area declaration"        "$fix/paths-outside-areas/filter.sh" "$fix/paths-outside-areas/catalog.yaml"
run 2 "a paths: key inside areas: but with no containing area is a hard error, not silently accepted" "$fix/paths-without-area/filter.sh" "$fix/paths-without-area/catalog.yaml"
run 2 "a CRLF line ending in the filter file is a hard error"             "$fix/crlf-line-ending/filter.sh" "$fix/synced/catalog.yaml"
run 2 "a column-zero comment doesn't end the areas: block early"          "$fix/duplicate-paths-key-column-zero-comment/filter.sh" "$fix/duplicate-paths-key-column-zero-comment/catalog.yaml"
run 2 "a duplicate area identifier is a hard error, not two areas"        "$fix/duplicate-area-identifier/filter.sh" "$fix/duplicate-area-identifier/catalog.yaml"
run 2 "a duplicate top-level areas: key is a hard error, not a second block to scan" "$fix/duplicate-areas-key/filter.sh" "$fix/duplicate-areas-key/catalog.yaml"
run 2 "a quoted duplicate of the top-level areas: key is a hard error, quotes and all" "$fix/quoted-areas-key-duplicate/filter.sh" "$fix/quoted-areas-key-duplicate/catalog.yaml"
run 2 "a bare duplicate areas: key with space before the colon is still a hard error" "$fix/spaced-areas-key-duplicate/filter.sh" "$fix/spaced-areas-key-duplicate/catalog.yaml"
run 2 "a quoted duplicate areas: key with space before the colon is still a hard error" "$fix/spaced-quoted-areas-key-duplicate/filter.sh" "$fix/spaced-quoted-areas-key-duplicate/catalog.yaml"
run 2 "a duplicate areas: key spelled with an unsupported YAML escape is a hard error, not invisible" "$fix/escaped-areas-key-duplicate/filter.sh" "$fix/escaped-areas-key-duplicate/catalog.yaml"
run 2 "an areas: key with trailing content is a hard error, not a nested mapping" "$fix/areas-key-trailing-content/filter.sh" "$fix/areas-key-trailing-content/catalog.yaml"
run 2 "a 2-space line with no colon is not a valid area declaration" "$fix/colonless-area-line/filter.sh" "$fix/colonless-area-line/catalog.yaml"
run 2 "an area name with trailing content is a hard error, not a nested mapping" "$fix/area-name-trailing-content/filter.sh" "$fix/area-name-trailing-content/catalog.yaml"
run 2 "an anchor-prefixed duplicate areas: key is a hard error, not a silent end of block" "$fix/anchor-prefixed-areas-key-duplicate/filter.sh" "$fix/anchor-prefixed-areas-key-duplicate/catalog.yaml"
run 0 "a single YAML anchor after areas: still declares a normal areas: block"    "$fix/areas-key-anchor-ok/filter.sh" "$fix/areas-key-anchor-ok/catalog.yaml"
run 0 "a single YAML anchor after an area name still declares a normal area"     "$fix/area-name-anchor-ok/filter.sh" "$fix/area-name-anchor-ok/catalog.yaml"
run 0 "an anchor and a tag together after areas: still declare a normal areas: block" "$fix/areas-key-anchor-and-tag-ok/filter.sh" "$fix/areas-key-anchor-and-tag-ok/catalog.yaml"
run 2 "two anchors after areas: is a hard error, not the supported anchor-plus-tag form" "$fix/areas-key-duplicate-anchor/filter.sh" "$fix/areas-key-duplicate-anchor/catalog.yaml"
run 2 "a # with no preceding whitespace after an anchor is a hard error, not valid anchor content" "$fix/areas-key-anchor-with-hash-rejected/filter.sh" "$fix/areas-key-anchor-with-hash-rejected/catalog.yaml"
run 2 "a # immediately after the areas: colon (no separating whitespace) is a hard error, not a trailing comment" "$fix/areas-key-colon-adjacent-hash-rejected/filter.sh" "$fix/areas-key-colon-adjacent-hash-rejected/catalog.yaml"
run 2 "a flow indicator (,) in an anchor name is a hard error, not valid anchor content" "$fix/areas-key-anchor-flow-indicator-rejected/filter.sh" "$fix/areas-key-anchor-flow-indicator-rejected/catalog.yaml"
run 2 "a flow indicator (,) in a tag name is a hard error, same as in an anchor" "$fix/areas-key-tag-flow-indicator-rejected/filter.sh" "$fix/areas-key-tag-flow-indicator-rejected/catalog.yaml"
run 2 "an angle bracket in a tag name is a hard error" "$fix/areas-key-tag-invalid-char-rejected/filter.sh" "$fix/areas-key-tag-invalid-char-rejected/catalog.yaml"
run 2 "a colon inside an area line's trailing comment is not the mapping colon" "$fix/area-name-comment-colon-rejected/filter.sh" "$fix/area-name-comment-colon-rejected/catalog.yaml"
run 2 "a non-mapping core tag (!!str) on areas: is a hard error" "$fix/areas-key-non-mapping-core-tag-rejected/filter.sh" "$fix/areas-key-non-mapping-core-tag-rejected/catalog.yaml"
run 2 "a --- multi-document catalog is a hard error, not scanned past into a second document" "$fix/multi-document-catalog-rejected/filter.sh" "$fix/multi-document-catalog-rejected/catalog.yaml"
run 2 "a ... document-end marker is a hard error too, same as ---" "$fix/document-end-marker-catalog-rejected/filter.sh" "$fix/document-end-marker-catalog-rejected/catalog.yaml"
run 0 "a leading --- before any real content is a legitimate single-document marker, not a hard error" "$fix/leading-document-start-marker-ok/filter.sh" "$fix/leading-document-start-marker-ok/catalog.yaml"
run 0 "a trailing ... with nothing after it is a legitimate single-document marker, not a hard error" "$fix/trailing-document-end-marker-ok/filter.sh" "$fix/trailing-document-end-marker-ok/catalog.yaml"
run 2 "two consecutive --- markers is a hard error, not tolerated as a single leading marker" "$fix/repeated-document-start-marker-rejected/filter.sh" "$fix/repeated-document-start-marker-rejected/catalog.yaml"
run 2 "a YAML sequence entry under areas: is a hard error, not harvested as an area name" "$fix/areas-sequence-entry-rejected/filter.sh" "$fix/areas-sequence-entry-rejected/catalog.yaml"
run 2 "a document marker with trailing scalar content (--- junk) is a hard error, not a bare decoration" "$fix/document-marker-scalar-content-rejected/filter.sh" "$fix/document-marker-scalar-content-rejected/catalog.yaml"
run 0 "a custom tag's resolvability is the adopter's own concern, not this scanner's — character-valid custom tags stay permissive" "$fix/areas-key-custom-tag-ok/filter.sh" "$fix/areas-key-custom-tag-ok/catalog.yaml"
run 2 "an anchor-prefixed duplicate area name is a hard error"                    "$fix/anchor-prefixed-area-name-duplicate/filter.sh" "$fix/anchor-prefixed-area-name-duplicate/catalog.yaml"
run 2 "an anchor-prefixed duplicate paths: key is a hard error"                   "$fix/anchor-prefixed-paths-key-duplicate/filter.sh" "$fix/anchor-prefixed-paths-key-duplicate/catalog.yaml"
run 2 "an explicit-key (? areas) duplicate of the areas: key is a hard error"     "$fix/explicit-key-areas-duplicate/filter.sh" "$fix/explicit-key-areas-duplicate/catalog.yaml"
run 2 "an anchor-prefixed duplicate areas: key is a hard error even after an unrelated top-level section" "$fix/anchor-prefixed-areas-key-after-other-section/filter.sh" "$fix/anchor-prefixed-areas-key-after-other-section/catalog.yaml"
run 2 "an anchor-prefixed areas: key is a hard error even when it comes before the plain areas: key" "$fix/anchor-prefixed-areas-key-duplicate-first/filter.sh" "$fix/anchor-prefixed-areas-key-duplicate-first/catalog.yaml"
run 2 "an explicit-key (? areas) duplicate is a hard error even when it comes before the plain areas: key" "$fix/explicit-key-areas-duplicate-first/filter.sh" "$fix/explicit-key-areas-duplicate-first/catalog.yaml"
run 2 "a double-quoted duplicate area identifier is a hard error, quotes and all" "$fix/quoted-area-identifier-duplicate/filter.sh" "$fix/quoted-area-identifier-duplicate/catalog.yaml"
run 2 "a single-quoted duplicate area identifier is a hard error, quotes and all" "$fix/single-quoted-area-identifier-duplicate/filter.sh" "$fix/single-quoted-area-identifier-duplicate/catalog.yaml"
run 2 "a quoted duplicate area identifier with space before the colon is still a hard error" "$fix/spaced-area-identifier-duplicate/filter.sh" "$fix/spaced-area-identifier-duplicate/catalog.yaml"
run 2 "an area identifier with an unsupported YAML escape is a hard error, not silently compared undecoded" "$fix/escaped-area-identifier-duplicate/filter.sh" "$fix/escaped-area-identifier-duplicate/catalog.yaml"
run 2 "a duplicate area identifier where one form uses a supported \\\" escape is still a hard error" "$fix/escaped-quote-area-identifier-duplicate/filter.sh" "$fix/escaped-quote-area-identifier-duplicate/catalog.yaml"
run 2 "a duplicate area identifier where one form uses YAML's doubled single-quote escape is still a hard error" "$fix/doubled-quote-area-identifier-duplicate/filter.sh" "$fix/doubled-quote-area-identifier-duplicate/catalog.yaml"
run 0 "a paths: key with space before the colon still declares the area's paths"    "$fix/spaced-paths-key/filter.sh" "$fix/spaced-paths-key/catalog.yaml"
run 2 "a quoted duplicate paths: key within the same area is a hard error, quotes and all" "$fix/quoted-paths-key-duplicate/filter.sh" "$fix/quoted-paths-key-duplicate/catalog.yaml"
run 2 "a duplicate paths: key spelled with an unsupported YAML escape is a hard error, not invisible" "$fix/escaped-paths-key-duplicate/filter.sh" "$fix/escaped-paths-key-duplicate/catalog.yaml"
run 2 "an area missing paths: in the middle of the block is a hard error, not masked by another area's glob" "$fix/area-missing-paths-middle/filter.sh" "$fix/area-missing-paths-middle/catalog.yaml"
run 2 "an area missing paths: as the last area in the file is a hard error at EOF" "$fix/area-missing-paths-last/filter.sh" "$fix/area-missing-paths-last/catalog.yaml"

[ "$rc" -eq 0 ] && echo "All regex-mirror self-tests passed." || echo "Regex-mirror self-tests FAILED."
exit "$rc"
